SELECT mi1.info, pi.info, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_867
WHERE (rt.role IN ('actor','cinematographer','composer','director','editor','guest','production designer','writer')) AND (kt.kind IN ('tv mini series','tv movie','tv series','video game','video movie')) AND it2.id = non_leaf_867.pi_info_type_id AND (mi1.info ILIKE '%72%') AND (it1.id IN ('107')) AND (pi.info ILIKE '%IS%') AND (it2.id IN ('37'));